    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xA993D69664B0971BULL + 0xEE47BDFAA8220E83ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xC06D500E2BA160BFULL + 0xA8A3CCF33502049BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xD20F049C48F45BC9ULL + 0xF28CAB91C5CD29B1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xF2BE73C7AAA78D69ULL + 0xD716D23C990445D8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0x8CD24681169839FFULL + 0xA11E73CDB9C3F84DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xD079FA3AC3D5124BULL + 0xA9C4A78E1D1D6CE2ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0x84CBECF2260BB7C3ULL + 0x9353133F4B0A2C23ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xE2220B24ECCD8EBFULL + 0xE93B31B8FE68CFCCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseB(pNonce * 0xC8F1C542A61D8C4FULL + 0xD4C3566E92706A35ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0x8D8CCA25CB6F2CE7ULL + 0x9B2B89615878959BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xF7669886B53A0DF5ULL + 0xFC62CD8544A7C85BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xB3BF173AE9D724F9ULL + 0xA589E3CC0C0DBB0BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseB(pNonce * 0xC75BD880B5E80B87ULL + 0xD5DEA4192E088524ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xB9D0144CF42D173DULL + 0xC6DC6084D7852182ULL);
