            aCross = RotL64(aSource[((S_BLOCK1 - aIndex + 110U)) & S_BLOCK1], 41U) ^ RotL64(pSnowLaneB[((S_BLOCK1 - aIndex + 4799U)) & S_BLOCK1], 12U);
            aCross = TwistMix64::DiffuseA(((aCross ^ aDomainWordCross) ^ aNonceWordI));
            //
            aScatter = (RotL64(aCarry, 43U) + RotL64(aIngress, 19U)) ^ (RotL64(aCross, 56U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseC(((aScatter ^ aDomainWordScatter) ^ aNonceWordL));
            //
            aOrbiterD = ((aWandererB + RotL64(aIngress, 13U)) + 0x36852EF5822432F2ULL) + aOrbiterAssignSaltC[((aIndex + 20U)) & S_SALT1];
