    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0x890D4B69C37B170BULL + 0xE0750CF9D5139A5DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0x9D7DE2F054388F0BULL + 0xD4517D4A4084719DULL);
