            aOrbiterD = RotL64((aOrbiterD * 0xE71D6762F677EEEBULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xA36437BC177A8102ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0x0F73F33CE0A3E5B1ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x582ACA2A54B0E799ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x7B57EC6E941EC975ULL;
