            aOrbiterB = ((aWandererF + RotL64(aScatter, 27U)) + 0xC27F09F109BB76F9ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aIngress, 23U)) + RotL64(aCarry, 39U)) + 0x0914FA8A7F5D8A55ULL;
            aOrbiterE = ((aWandererE + RotL64(aPrevious, 13U)) + 0x41BCA4A558CD8603ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = (aWandererC + RotL64(aCross, 6U)) + 0xC23528B529AF24AEULL;
            aOrbiterF = ((aWandererK + RotL64(aScatter, 57U)) + RotL64(aCarry, 47U)) + 0x2DEAB5A289895B55ULL;
            aOrbiterA = (aWandererH + RotL64(aPrevious, 39U)) + 0xAE07BCCFB7B627A8ULL;
