            aOrbiterI = RotL64((aOrbiterI * 0x5C7286ACC5220B67ULL), 53U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x0EC3EEDF9BA44557ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0x9A532149CCEEDC35ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x17D8E45AD7B3BC15ULL), 43U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x58F68E1D0ECE7C5DULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x2265CFAD85188299ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x4636FAC202FEA787ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xF89686087ACEB4DCULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0xCEAAB32CC9025E74ULL;
