            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x30687B5A733335E0ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x8F1BF942A6E23157ULL;
