            aOrbiterB = ((aWandererE + RotL64(aCross, 39U)) + RotL64(aCarry, 27U)) + 0xC96047AD09BA0640ULL;
            aOrbiterJ = (aWandererH + RotL64(aIngress, 23U)) + 0x6F0E75D8FDFCD39DULL;
            aOrbiterD = (((aWandererC + RotL64(aScatter, 53U)) + RotL64(aCarry, 57U)) + 0xC5A9D996064DB546ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterF = (aWandererF + RotL64(aIngress, 35U)) + 0x5F732495EC27CBF5ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xDDCD69C09F6F908CULL;
