            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x38B49F5D0BA881AEULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0xE0513AB8B422D720ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA03D80C49FDDE86DULL), 13U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0xE7C21BB0F9A6A543ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xD561293BD0F62F67ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x39236DF532886DA9ULL), 3U);
