            aIngress ^= (RotL64(aMagmaLaneC[((aIndex + 8928U)) & S_BLOCK1], 21U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 12989U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
