            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 15886U)) & S_BLOCK1], 48U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 9762U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 8946U)) & W_KEY1], 21U) ^ RotL64(aEarthLaneA[((aIndex + 15292U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 19U) ^ RotL64(aCross, 36U)) ^ (RotL64(aCarry, 53U) + RotL64(aIngress, 3U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
